#include <cstdio>
#include <array>
using namespace std;

const int MAX_X = 10000;

int main() {
    array<bool, MAX_X + 1> prime;
    prime.fill(true);
    prime[0] = prime[1] = false; // 0 and 1 are not prime
    int n;

    // Sieve of Eratosthenes
    for (int i = 2; i * i <= MAX_X; i++) {
        if (prime[i]) {
            for (int k = i * i; k <= MAX_X; k += i) { // Start from i*i
                prime[k] = false;
            }
        }
    }

    while (true) {
        scanf("%d", &n);
        if (n == 0) break;

        int max = -1;
        for (int i = n; i >= 3; i--) { // Start from 3 for twin primes
            if (prime[i] && prime[i - 2]) {
                max = i;
                break;
            }
        }

        if (max != -1)
            printf("%d %d\n", max - 2, max);
    }

    return 0;
}

